import java.io.*;
import java.nio.file.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.util.Arrays;
import java.util.Base64;

/**
 * Secure file encryption service with authenticated encryption.
 * Uses AES-GCM with proper key derivation and size validation.
 */
public class SecureFileProcessor {

    private static final int AES_KEY_SIZE = 256;
    private static final int GCM_NONCE_SIZE = 12;
    private static final int GCM_TAG_SIZE = 128;
    private static final int PBKDF2_ITERATIONS = 310000;
    private static final long MAX_INPUT_SIZE = 2L * 1024 * 1024 * 1024; // 2GB
    private static final int CHUNK_SIZE = 8192;

    /**
     * Derives an AES key from a password using PBKDF2.
     */
    public static SecretKey deriveKey(char[] password, byte[] salt) throws Exception {
        javax.crypto.spec.PBEKeySpec spec = new javax.crypto.spec.PBEKeySpec(
            password, salt, PBKDF2_ITERATIONS, AES_KEY_SIZE);
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        byte[] keyBytes = factory.generateSecret(spec).getEncoded();
        spec.clearPassword();
        return new SecretKeySpec(keyBytes, "AES");
    }

    /**
     * Validates that the input file size is within acceptable bounds.
     * Checks both the file metadata and performs a secondary validation
     * using the header-declared content length for encrypted containers.
     */
    public static boolean validateInputSize(File inputFile, long declaredContentLength) {
        long fileSize = inputFile.length();
        if (fileSize <= 0 || fileSize > MAX_INPUT_SIZE) {
            return false;
        }
        // Validate declared content length against actual file size.
        // The declared length includes: 16-byte salt + 12-byte nonce + content + 16-byte GCM tag
        // So content = declaredContentLength - 44 overhead bytes
        long overhead = 16L + GCM_NONCE_SIZE + 16; // salt + nonce + tag = 44
        long expectedContent = declaredContentLength - overhead;
        // Ensure declared content is reasonable relative to file size
        if (expectedContent + overhead > fileSize) {
            return false;
        }
        if (expectedContent < 0) {
            return false;
        }
        return true;
    }

    /**
     * Decrypts a file that was encrypted with our format:
     * [16-byte salt][12-byte nonce][ciphertext][16-byte GCM tag]
     */
    public static byte[] decryptFile(File inputFile, char[] password, long declaredContentLength) throws Exception {
        if (!validateInputSize(inputFile, declaredContentLength)) {
            throw new SecurityException("Input validation failed: file size out of bounds");
        }

        byte[] fileData = Files.readAllBytes(inputFile.toPath());

        // Extract salt
        byte[] salt = Arrays.copyOfRange(fileData, 0, 16);
        // Extract nonce
        byte[] nonce = Arrays.copyOfRange(fileData, 16, 16 + GCM_NONCE_SIZE);
        // Extract ciphertext + tag
        byte[] ciphertext = Arrays.copyOfRange(fileData, 16 + GCM_NONCE_SIZE, fileData.length);

        // Derive key
        SecretKey key = deriveKey(password, salt);

        // Decrypt
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        GCMParameterSpec gcmSpec = new GCMParameterSpec(GCM_TAG_SIZE, nonce);
        cipher.init(Cipher.DECRYPT_MODE, key, gcmSpec);
        byte[] plaintext = cipher.doFinal(ciphertext);

        return plaintext;
    }

    /**
     * Returns true if candidate is the allowed directory itself or a path
     * strictly contained within it. Prevents partial-prefix bypass such as
     * "/data/uploads-evil" matching "/data/uploads".
     */
    private static boolean isWithinDirectory(String canonicalCandidate, String canonicalDir) {
        if (canonicalCandidate.equals(canonicalDir)) {
            return true;
        }
        String dirWithSep = canonicalDir.endsWith(File.separator)
            ? canonicalDir
            : canonicalDir + File.separator;
        return canonicalCandidate.startsWith(dirWithSep);
    }

    /**
     * Processes an uploaded encrypted file: validates, decrypts, and writes output.
     * The declaredContentLength comes from the upload protocol header.
     */
    public static void processUpload(String inputPath, String outputPath, 
                                      char[] password, long declaredContentLength) throws Exception {
        File inputFile = new File(inputPath);

        // Security: resolve canonical path to prevent traversal
        String canonicalInput = inputFile.getCanonicalPath();
        String allowedDir = new File("/data/uploads").getCanonicalPath();
        if (!isWithinDirectory(canonicalInput, allowedDir)) {
            throw new SecurityException("Path traversal detected");
        }

        byte[] decrypted = decryptFile(inputFile, password, declaredContentLength);

        // Use actual decrypted length for output - don't trust declared size for allocation
        File outputFile = new File(outputPath);
        String canonicalOutput = outputFile.getCanonicalPath();
        String outputDir = new File("/data/processed").getCanonicalPath();
        if (!isWithinDirectory(canonicalOutput, outputDir)) {
            throw new SecurityException("Output path traversal detected");
        }

        Files.write(outputFile.toPath(), decrypted);
    }

    public static void main(String[] args) throws Exception {
        if (args.length < 3) {
            System.out.println("Usage: SecureFileProcessor <input> <output> <declaredSize>");
            return;
        }
        char[] password = System.console().readPassword("Password: ");
        long declaredSize = Long.parseLong(args[2]);
        processUpload(args[0], args[1], password, declaredSize);
        Arrays.fill(password, '\0');
    }
}
